definition:
CREATE OR REPLACE FUNCTION private.create_debt_contract(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions'
AS $function$
declare uid uuid:=auth.uid();org uuid:=(p->>'organization_id')::uuid;request uuid:=(p->>'request_id')::uuid;cid uuid;eid uuid;oid uuid;fid uuid;cls uuid;base text;fx numeric:=(p->>'exchange_rate')::numeric;amt numeric:=(p->>'principal')::numeric;dt date:=(p->>'date')::date;side text:=p->>'side';mode text:=p->>'mode';kind text:=p->>'kind';cat text:=p->>'category';hash text;obs jsonb:='[]';item jsonb;i int:=0;total numeric:=0;total_base numeric:=0;due date;prior public.debt_contracts%rowtype;bank public.liquidity_accounts%rowtype;
begin
 if uid is null then raise exception 'UNAUTHORIZED';end if;
 if not public.financial_core_can(org,'financial_core.view') or not public.financial_core_can(org,'financial_core.create') then raise exception 'DEBT_CONTRACT_ACCESS_DENIED';end if;
 perform pg_advisory_xact_lock(hashtextextended(org::text||'|DEBT_CONTRACT|'||request::text,0));
 hash:=encode(extensions.digest(p::text,'sha256'),'hex');select * into prior from public.debt_contracts where organization_id=org and request_id=request;
 if prior.id is not null then if prior.payload_fingerprint<>hash then raise exception 'DEBT_CONTRACT_REQUEST_CONFLICT';end if;return jsonb_build_object('id',prior.id,'eventId',prior.financial_event_id,'replay',true);end if;
 if side not in('RECEIVABLE','PAYABLE') or mode not in('OPENING','NEW') or kind not in('OPENING','LOAN','EMPLOYEE_ADVANCE') or(kind='OPENING' and mode<>'OPENING')or(kind='EMPLOYEE_ADVANCE' and side<>'RECEIVABLE') then raise exception 'DEBT_CONTRACT_INVALID';end if;
 if cat is null or cat not in('O_AR_CUSTOMER','O_AR_EMPLOYEE','O_AR_LOAN','O_AR_RELATED','O_AR_ACCRUED','O_AR_OTHER','O_AP_SUPPLIER','O_AP_ACCRUAL','O_AP_EMPLOYEE','O_AP_LOAN','O_AP_RELATED','O_AP_OTHER') or (side='RECEIVABLE' and cat not like 'O_AR_%')or(side='PAYABLE' and cat not like 'O_AP_%')or(kind='LOAN' and cat<>case when side='RECEIVABLE' then 'O_AR_LOAN' else 'O_AP_LOAN' end)or(kind='EMPLOYEE_ADVANCE' and cat<>'O_AR_EMPLOYEE') then raise exception 'DEBT_CATEGORY_SIDE_MISMATCH';end if;
 select base_currency into base from public.organizations where id=org;
 if amt is null or amt<=0 or amt::text in('NaN','Infinity','-Infinity')or amt<>round(amt,4) or fx is null or fx<=0 or fx::text in('NaN','Infinity','-Infinity') or(p->>'currency')!~'^[A-Z]{3}$'or(p->>'currency'=base and fx<>1) or dt is null or dt>(now() at time zone 'Asia/Riyadh')::date or length(trim(p->>'description')) not between 3 and 500 or length(trim(p->>'reference')) not between 1 and 120 then raise exception 'DEBT_CONTRACT_INVALID';end if;
 if not exists(select 1 from public.liquidity_counterparties where id=(p->>'counterparty_id')::uuid and organization_id=org and active)or(nullif(p->>'entity_id','')is not null and not exists(select 1 from public.organization_entities where id=(p->>'entity_id')::uuid and organization_id=org and active))then raise exception 'DEBT_CONTRACT_SCOPE_MISMATCH';end if;
 if mode='NEW' then
  if not public.effective_organization_permission(org,'liquidity.edit',null,null) then raise exception 'DEBT_CONTRACT_ACCESS_DENIED';end if;
  select * into bank from public.liquidity_accounts where id=(p->>'account_id')::uuid and organization_id=org and active;
  if bank.id is null or bank.currency<>p->>'currency' or(bank.entity_id is not null and bank.entity_id is distinct from nullif(p->>'entity_id','')::uuid)then raise exception 'DEBT_CONTRACT_ACCOUNT_MISMATCH';end if;
 end if;
 if jsonb_typeof(p->'schedule')<>'array' or jsonb_array_length(p->'schedule')not between 1 and 48 then raise exception 'DEBT_SCHEDULE_INVALID';end if;
 for item in select value from jsonb_array_elements(p->'schedule') loop
  i:=i+1;due:=(item->>'due_date')::date;
  if(item->>'amount')::numeric is null or(item->>'amount')::numeric<=0 or(item->>'amount')::numeric::text in('NaN','Infinity','-Infinity')or(item->>'amount')::numeric<>round((item->>'amount')::numeric,4)or round((item->>'amount')::numeric*fx,4)<=0 or due is null or due<dt then raise exception 'DEBT_SCHEDULE_INVALID';end if;
  total:=total+(item->>'amount')::numeric;total_base:=total_base+round((item->>'amount')::numeric*fx,4);
  obs:=obs||jsonb_build_array(jsonb_build_object('obligation_key','installment:'||i,'obligation_type',side,'settleable_amount',(item->>'amount')::numeric,'currency',p->>'currency','exchange_rate',fx,'base_currency',base,'settleable_base_amount',round((item->>'amount')::numeric*fx,4)));
 end loop;
 if total<>amt or total_base<>round(amt*fx,4)then raise exception 'DEBT_SCHEDULE_TOTAL_MISMATCH';end if;
 insert into public.financial_classifications(organization_id,code,name,classification_type,is_system,created_by)select org,v.code,v.name,v.kind,true,uid from(values('DEBT_PRINCIPAL_ASSET','أصول القروض والذمم','ASSET'),('DEBT_PRINCIPAL_LIABILITY','التزامات القروض والذمم','LIABILITY'),('DEBT_RECEIVABLE_CLEARING','تحصيل أصل الذمة','RECEIVABLE'),('DEBT_PAYABLE_CLEARING','سداد أصل الذمة','PAYABLE'))v(code,name,kind)on conflict(organization_id,code)do nothing;
 select id into cls from public.financial_classifications where organization_id=org and classification_type=(case when side='RECEIVABLE' then 'ASSET' else 'LIABILITY' end) and active order by id limit 1;
 if cls is null then raise exception 'DEBT_CLASSIFICATION_REQUIRED';end if;
 insert into public.debt_contracts(organization_id,request_id,kind,mode,side,counterparty_id,entity_id,account_id,category,description,reference,event_date,currency,exchange_rate,principal,schedule,payload_fingerprint,created_by)
 values(org,request,kind,mode,side,(p->>'counterparty_id')::uuid,nullif(p->>'entity_id','')::uuid,case when mode='NEW' then bank.id else null end,cat,trim(p->>'description'),trim(p->>'reference'),dt,p->>'currency',fx,amt,p->'schedule',hash,uid)returning id into cid;
 eid:=public.create_financial_event_command(jsonb_build_object('organization_id',org,'entity_id',nullif(p->>'entity_id','')::uuid,'counterparty_id',(p->>'counterparty_id')::uuid,'event_type','ADJUSTMENT','source_module','DEBT_CONTRACTS','source_record_id',cid,'source_event_key','debt-contract:'||cid,'event_date',dt,'due_date',null,'base_currency',base,'description',trim(p->>'description'),'lines',jsonb_build_array(jsonb_build_object('line_number',1,'classification_id',cls,'description',trim(p->>'description'),'amount',amt,'currency',p->>'currency','exchange_rate',fx,'base_amount',round(amt*fx,4),'cash_direction',
    case
      when mode='NEW' and side='RECEIVABLE' then 'OUTFLOW'
      when mode='NEW' and side='PAYABLE' then 'INFLOW'
      else 'NON_CASH'
    end,
    'vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0)),'obligations',obs,'links',jsonb_build_array(jsonb_build_object('link_type','SOURCE','target_module','debt_contracts','target_record_id',cid))));
 update public.debt_contracts set financial_event_id=eid where id=cid;
 perform public.transition_financial_event(eid,'PLANNED','Debt contract prepared');perform public.transition_financial_event(eid,'COMMITTED','Awaiting contract approval');
 return jsonb_build_object('id',cid,'eventId',eid,'status','COMMITTED');
end $function$

CREATE OR REPLACE FUNCTION private.prepare_debt_operation(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare uid uuid:=auth.uid();org uuid:=(p->>'organization_id')::uuid;req uuid:=(p->>'request_id')::uuid;kind text:=p->>'kind';target uuid:=(p->>'target_id')::uuid;
 r public.debt_operation_requests%rowtype;c public.debt_contracts%rowtype;e public.financial_events%rowtype;o public.financial_event_obligations%rowtype;s public.liquidity_settlements%rowtype;
 amount numeric;fx numeric;ccy text;base text;direction text;cls uuid;eid uuid;obs jsonb:='[]';links jsonb:='[]';body jsonb:=p;fingerprint text;dt date:=(p->>'date')::date;party uuid;entity uuid;
begin
 if uid is null then raise exception 'UNAUTHORIZED';end if;
 if not public.financial_core_can(org,'financial_core.view')or not public.financial_core_can(org,'financial_core.create')then raise exception 'DEBT_OPERATION_ACCESS_DENIED';end if;
 if req is null or target is null or kind is null or kind not in('RESCHEDULE','REFUND','REVERSE')or dt is null or dt>(now()at time zone 'Asia/Riyadh')::date or length(trim(coalesce(p->>'reason','')))not between 5 and 500 then raise exception 'DEBT_OPERATION_INVALID';end if;
 perform pg_advisory_xact_lock(hashtextextended(org::text||'|PHASE2B_CASH_WRITE',0));fingerprint:=md5(p::text);
 select * into r from public.debt_operation_requests where organization_id=org and request_id=req;
 if r.id is not null then if r.fingerprint<>fingerprint then raise exception 'DEBT_OPERATION_REQUEST_CONFLICT';end if;return jsonb_build_object('id',r.id,'eventId',r.financial_event_id,'replay',true);end if;
 if kind='RESCHEDULE'then
  select * into c from public.debt_contracts where id=target and organization_id=org;
  select * into e from public.financial_events where id=c.financial_event_id and status='ACTUAL';
  if e.id is null or c.kind not in('LOAN','EMPLOYEE_ADVANCE')then raise exception 'DEBT_OPERATION_SOURCE_INVALID';end if;
  if jsonb_typeof(p->'dates')is distinct from 'array'or jsonb_array_length(p->'dates')not between 1 and 48 then raise exception 'DEBT_SCHEDULE_INVALID';end if;
  body:=p||jsonb_build_object('schedule_before',c.schedule);amount:=c.principal;fx:=c.exchange_rate;ccy:=c.currency;base:=e.base_currency;direction:='NON_CASH';
 elsif kind='REFUND'then
  select * into o from public.financial_event_obligations where id=target and organization_id=org and adjusts_obligation_id is null and obligation_type in('SUPPLIER_ADVANCE','CUSTOMER_ADVANCE');
  select * into e from public.financial_events where id=o.event_id and status='ACTUAL';
  amount:=(p->>'amount')::numeric;fx:=o.exchange_rate;ccy:=o.currency;base:=o.base_currency;
  if e.id is null or e.source_module not in('ADVANCE_WORKSPACE','OPERATIONAL_CONSOLE')or amount is null or amount<=0 or amount>1e12 or amount::text in('NaN','Infinity','-Infinity')or amount<>round(amount,4)or round(amount*fx,4)<=0 or round(amount*fx,4)>(select outstanding_base_amount from public.financial_event_obligation_balances where obligation_id=o.id)then raise exception 'ADVANCE_EXCEEDS_BALANCE';end if;
  direction:=case when o.obligation_type='SUPPLIER_ADVANCE'then 'INFLOW'else 'OUTFLOW'end;
  obs:=jsonb_build_array(jsonb_build_object('obligation_key','refund','obligation_type',o.obligation_type,'adjusts_obligation_id',o.id,'adjustment_effect','DECREASE','settleable_amount',amount,'currency',ccy,'exchange_rate',fx,'base_currency',base,'settleable_base_amount',round(amount*fx,4)));
 else
  select * into e from public.financial_events where id=target and organization_id=org and status='ACTUAL';
  if e.id is null or e.source_module not in('ADVANCE_WORKSPACE','OPERATIONAL_CONSOLE','DEBT_OPERATIONS','DEBT_CONTRACTS')then raise exception 'DEBT_OPERATION_SOURCE_INVALID';end if;
  if not public.financial_core_can(org,'financial_core.reverse')then raise exception 'DEBT_OPERATION_ACCESS_DENIED';end if;
  select * into s from public.liquidity_settlements where financial_event_id=e.id and organization_id=org and status='POSTED';
  if s.id is not null then amount:=s.amount;fx:=s.exchange_rate;ccy:=s.currency;base:=s.base_currency;direction:=case when s.direction='INFLOW'then 'OUTFLOW'else 'INFLOW'end;body:=p||jsonb_build_object('settlement_id',s.id);
  elsif e.source_module='DEBT_CONTRACTS'then
   select * into c from public.debt_contracts where financial_event_id=e.id and organization_id=org;amount:=c.principal;fx:=c.exchange_rate;ccy:=c.currency;base:=e.base_currency;direction:='NON_CASH';
  elsif exists(select 1 from public.financial_event_command_registry where financial_event_id=e.id and command_type='ADVANCE_APPLICATION')then
   select sum(a.amount),max(a.exchange_rate),max(a.currency),max(a.base_currency)into amount,fx,ccy,base from public.financial_event_obligation_allocations a where application_event_id=e.id and allocation_type='ADVANCE_APPLICATION';direction:='NON_CASH';
  else raise exception 'DEBT_OPERATION_SOURCE_INVALID';end if;
  links:=jsonb_build_array(jsonb_build_object('link_type','REVERSAL_OF','related_event_id',e.id));
 end if;
 if dt<e.event_date then raise exception 'DEBT_OPERATION_DATE_INVALID';end if;party:=e.counterparty_id;entity:=e.entity_id;
 -- A clearing classification cannot recognize income, expense, VAT or another principal.
 select id into cls from public.financial_classifications where organization_id=org and classification_type=case when direction='INFLOW'then 'RECEIVABLE'else 'PAYABLE'end and active order by id limit 1;
 if cls is null then raise exception 'SETTLEMENT_CLASSIFICATION_REQUIRED';end if;
 eid:=public.create_financial_event_command(jsonb_build_object('organization_id',org,'entity_id',entity,'counterparty_id',party,'event_type',case when kind='REVERSE'then 'REVERSAL'when kind='REFUND'then 'SETTLEMENT'else 'ADJUSTMENT'end,'source_module','DEBT_OPERATIONS','source_event_key','debt-operation:'||req,'event_date',dt,'due_date',null,'base_currency',base,'description',p->>'reason','lines',jsonb_build_array(jsonb_build_object('line_number',1,'classification_id',cls,'description',p->>'reason','amount',amount,'currency',ccy,'exchange_rate',fx,'base_amount',round(amount*fx,4),'cash_direction',direction,'vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0)),'obligations',obs,'links',links));
 insert into public.debt_operation_requests(organization_id,request_id,kind,target_id,payload,fingerprint,financial_event_id,created_by)values(org,req,kind,target,body,fingerprint,eid,uid)returning * into r;
 perform public.transition_financial_event(eid,'PLANNED','Source operation prepared');perform public.transition_financial_event(eid,'COMMITTED','Awaiting approval');
 return jsonb_build_object('id',r.id,'eventId',eid);
end $function$

CREATE OR REPLACE FUNCTION public.amend_unissued_sales_invoice(p_document_id uuid, p_document_number text, p_transaction_date date, p_due_date date, p_contact_id uuid, p_counterparty_name text, p_counterparty_tax_number text, p_supply_type text, p_net numeric, p_tax_rate numeric, p_tax numeric, p_gross numeric, p_line_items jsonb, p_notes text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_org uuid; v_event uuid; v_flow uuid; v_counterparty uuid; v_revenue_class uuid; v_tax_class uuid; v_tax_line uuid; v_settled numeric;
begin
 select organization_id into v_org from public.vat_documents where id=p_document_id and document_type='SALES' and document_kind='INVOICE' for update;
 if v_org is null then raise exception 'VAT_DOCUMENT_NOT_FOUND'; end if;
 if not public.is_organization_admin(v_org) then raise exception 'ORGANIZATION_ADMIN_REQUIRED'; end if;
 if exists(select 1 from public.vat_einvoices where accounting_document_id=p_document_id and status in ('ISSUED','SUBMITTED','CLEARED','REPORTED')) then raise exception 'VAT_DOCUMENT_ISSUED_LOCKED'; end if;
 select id,settled_amount into v_flow,v_settled from public.liquidity_flows where organization_id=v_org and source_module='VAT_INTEGRATION' and source_record_id=p_document_id order by created_at limit 1 for update;
 if coalesce(v_settled,0)>0 then raise exception 'VAT_DOCUMENT_SETTLED_LOCKED'; end if;
 select event_id into v_event from public.financial_event_links where organization_id=v_org and link_type='SOURCE' and target_module='vat_documents' and target_record_id=p_document_id limit 1;
 if v_event is null then raise exception 'VAT_FINANCIAL_EVENT_REQUIRED'; end if;
 select m.counterparty_id into v_counterparty from public.financial_vat_counterparty_map m where m.organization_id=v_org and m.vat_contact_id=p_contact_id;
 if v_counterparty is null then raise exception 'VAT_COUNTERPARTY_MAPPING_REQUIRED'; end if;
 select id into v_revenue_class from public.financial_classifications where organization_id=v_org and classification_type='REVENUE' and active=true limit 1;
 select id into v_tax_class from public.financial_classifications where organization_id=v_org and classification_type='TAX' and active=true limit 1;
 if v_revenue_class is null or v_tax_class is null then raise exception 'VAT_FINANCIAL_CLASSIFICATIONS_REQUIRED'; end if;

 update public.vat_documents set document_number=p_document_number,transaction_date=p_transaction_date,due_date=p_due_date,
  counterparty_contact_id=p_contact_id,counterparty_name=p_counterparty_name,counterparty_tax_number=nullif(p_counterparty_tax_number,''),
  supply_type=p_supply_type,net_amount=p_net,tax_rate=p_tax_rate,tax_amount=p_tax,gross_amount=p_gross,line_items=p_line_items,
  source_net_amount=p_net,source_tax_amount=p_tax,source_gross_amount=p_gross,notes=p_notes
 where id=p_document_id;

 update public.financial_events set counterparty_id=v_counterparty,event_date=p_transaction_date,due_date=p_due_date,
  description='Sales invoice '||p_document_number,updated_at=now() where id=v_event and status in ('DRAFT','PLANNED','COMMITTED');
 if not found then raise exception 'VAT_FINANCIAL_EVENT_LOCKED'; end if;

 update public.financial_event_lines set amount=p_net,base_amount=p_net,description='Sales revenue recognition'
 where event_id=v_event and classification_id=v_revenue_class;
 select id into v_tax_line from public.financial_event_lines where event_id=v_event and classification_id=v_tax_class limit 1;
 if p_tax>0 then
   if v_tax_line is null then
     insert into public.financial_event_lines(event_id,organization_id,line_number,description,classification_id,cost_center_id,amount,currency,exchange_rate,base_amount,cash_direction,vat_treatment,vat_rate,vat_amount)
     select v_event,v_org,coalesce((select max(line_number) from public.financial_event_lines where event_id=v_event),0)+1,'Output VAT recognition',v_tax_class,null,p_tax,base_currency,1,p_tax,'NON_CASH','OUT_OF_SCOPE',0,0 from public.financial_events where id=v_event;
   else update public.financial_event_lines set amount=p_tax,base_amount=p_tax,description='Output VAT recognition' where id=v_tax_line; end if;
 elsif v_tax_line is not null then delete from public.financial_event_lines where id=v_tax_line; end if;

 update public.financial_event_obligations set settleable_amount=p_gross,settleable_base_amount=p_gross where event_id=v_event and obligation_type='RECEIVABLE';
 update public.liquidity_flows set due_date=p_due_date,amount=p_gross,base_amount=p_gross,counterparty=p_counterparty_name,counterparty_id=v_counterparty,
  reference=p_document_number,title='Invoice receivable · '||p_document_number,updated_at=now()
 where id=v_flow;
 return p_document_id;
end $function$

CREATE OR REPLACE FUNCTION public.amend_unsettled_purchase_invoice(p_document_id uuid, p_document_number text, p_transaction_date date, p_due_date date, p_contact_id uuid, p_counterparty_name text, p_counterparty_tax_number text, p_supply_type text, p_net numeric, p_tax_rate numeric, p_tax numeric, p_gross numeric, p_recoverable_percent numeric, p_line_items jsonb, p_notes text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_org uuid; v_event uuid; v_counterparty uuid; v_opex uuid; v_tax_class uuid; v_flow uuid; v_settled numeric:=0; v_currency text;
begin
 select organization_id,currency into v_org,v_currency from public.vat_documents where id=p_document_id and document_type='PURCHASE' and document_kind='INVOICE' and asset_transaction_id is null for update;
 if v_org is null then raise exception 'VAT_PURCHASE_EDIT_NOT_ALLOWED'; end if;
 if not public.is_organization_admin(v_org) then raise exception 'ORGANIZATION_ADMIN_REQUIRED'; end if;
 select event_id into v_event from public.financial_event_links where organization_id=v_org and link_type='SOURCE' and target_module='vat_documents' and target_record_id=p_document_id limit 1;
 if v_event is null then raise exception 'VAT_FINANCIAL_EVENT_REQUIRED'; end if;
 select coalesce(settled_amount,0),id into v_settled,v_flow from public.liquidity_flows where organization_id=v_org and source_module='VAT_INTEGRATION' and source_record_id=p_document_id order by created_at limit 1 for update;
 if v_settled>0 then raise exception 'VAT_DOCUMENT_SETTLED_LOCKED'; end if;
 if exists(select 1 from public.financial_event_obligation_allocations a join public.financial_event_obligations o on o.id=a.obligation_id where o.event_id=v_event) then raise exception 'VAT_DOCUMENT_SETTLED_LOCKED'; end if;
 select counterparty_id into v_counterparty from public.financial_vat_counterparty_map where organization_id=v_org and vat_contact_id=p_contact_id;
 if v_counterparty is null then raise exception 'VAT_COUNTERPARTY_MAPPING_REQUIRED'; end if;
 select id into v_opex from public.financial_classifications where organization_id=v_org and classification_type='OPEX' and code='OPEX' and active=true limit 1;
 select id into v_tax_class from public.financial_classifications where organization_id=v_org and classification_type='TAX' and active=true limit 1;
 if v_opex is null or v_tax_class is null then raise exception 'VAT_FINANCIAL_CLASSIFICATIONS_REQUIRED'; end if;
 update public.vat_documents set document_number=p_document_number,transaction_date=p_transaction_date,due_date=p_due_date,counterparty_contact_id=p_contact_id,counterparty_name=p_counterparty_name,counterparty_tax_number=nullif(p_counterparty_tax_number,''),supply_type=p_supply_type,net_amount=p_net,tax_rate=p_tax_rate,tax_amount=p_tax,gross_amount=p_gross,recoverable_percent=p_recoverable_percent,line_items=p_line_items,source_net_amount=p_net,source_tax_amount=p_tax,source_gross_amount=p_gross,notes=p_notes where id=p_document_id;
 update public.financial_events set counterparty_id=v_counterparty,event_date=p_transaction_date,due_date=p_due_date,description='Purchase invoice '||p_document_number,updated_at=now() where id=v_event and status in ('DRAFT','PLANNED','COMMITTED');
 if not found then raise exception 'VAT_FINANCIAL_EVENT_LOCKED'; end if;
 update public.financial_event_lines set amount=p_net,base_amount=p_net where event_id=v_event and classification_id=v_opex;
 update public.financial_event_lines set amount=p_tax,base_amount=p_tax where event_id=v_event and classification_id=v_tax_class;
 update public.financial_event_obligations set settleable_amount=p_gross,settleable_base_amount=p_gross where event_id=v_event and obligation_type='PAYABLE';
 if v_flow is null then
   insert into public.liquidity_flows(organization_id,direction,flow_type,title,counterparty,counterparty_id,due_date,amount,currency,base_amount,status,source,reference,notes,source_module,source_record_id,source_event_key)
   values(v_org,'OUTFLOW','OPERATING','Invoice payable · '||p_document_number,p_counterparty_name,v_counterparty,p_due_date,p_gross,v_currency,p_gross,'EXPECTED','INVOICE',p_document_number,'Generated from invoice due date; settlement clears the linked Financial Core payable.','VAT_INTEGRATION',p_document_id,'vat_documents:'||p_document_id||':cash-forecast')
   returning id into v_flow;
   insert into public.financial_event_links(organization_id,event_id,link_type,target_module,target_record_id,metadata)
   values(v_org,v_event,'CASH_FLOW','liquidity_flows',v_flow,jsonb_build_object('purpose','INVOICE_DUE_FORECAST','due_date',p_due_date,'source_document_id',p_document_id));
 else
   update public.liquidity_flows set due_date=p_due_date,amount=p_gross,base_amount=p_gross,counterparty=p_counterparty_name,counterparty_id=v_counterparty,reference=p_document_number,title='Invoice payable · '||p_document_number,updated_at=now() where id=v_flow;
 end if;
 return p_document_id;
end $function$

CREATE OR REPLACE FUNCTION public.amend_zatca_draft_atomic(p_invoice_id uuid, p_header jsonb, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  e public.vat_einvoices%rowtype;
  h public.vat_einvoices%rowtype;
  d public.vat_documents%rowtype;
  v_event uuid; v_status text; v_counterparty uuid; v_tax_class uuid; v_base text;
  v_net numeric; v_tax numeric; v_gross numeric; v_source_net numeric; v_source_tax numeric;
  v_line_items jsonb; v_changed boolean;
begin
  if auth.uid() is null then raise exception 'UNAUTHORIZED'; end if;
  select * into e from public.vat_einvoices where id=p_invoice_id for update;
  if e.id is null then raise exception 'EINVOICE_DRAFT_NOT_FOUND'; end if;
  if not public.is_organization_admin(e.organization_id) then raise exception 'ORGANIZATION_ADMIN_REQUIRED'; end if;
  if e.status <> 'DRAFT' then raise exception 'EINVOICE_DRAFT_LOCKED'; end if;
  if (p_header->>'organization_id')::uuid is distinct from e.organization_id then raise exception 'EINVOICE_ACCOUNTING_SOURCE_MISMATCH'; end if;
  -- Only editable columns are copied below; IDs, lifecycle, QR and audit fields remain server-owned.
  h := jsonb_populate_record(e,p_header);
  if e.accounting_document_id is not null and h.accounting_document_id is distinct from e.accounting_document_id then
    raise exception 'EINVOICE_ACCOUNTING_SOURCE_MISMATCH';
  end if;
  if e.accounting_document_id is null then e.accounting_document_id := h.accounting_document_id; end if;
  if h.document_type is distinct from e.document_type then raise exception 'EINVOICE_ACCOUNTING_SOURCE_MISMATCH'; end if;
  if h.due_date is null then h.due_date := h.issue_date; end if;
  if h.due_date < h.issue_date then raise exception 'DUE_DATE_BEFORE_ISSUE_DATE'; end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) not between 1 and 500 then raise exception 'INVALID_EINVOICE_DRAFT'; end if;
  if exists(select 1 from jsonb_to_recordset(p_lines) as l(quantity numeric,unit_price numeric,discount_amount numeric,line_extension_amount numeric)
      where l.quantity<=0 or l.unit_price<0 or l.discount_amount<0 or l.line_extension_amount is distinct from round(l.quantity*l.unit_price-l.discount_amount,2)) then
    raise exception 'INVALID_EINVOICE_DRAFT';
  end if;
  select sum((l->>'line_extension_amount')::numeric) into v_source_net from jsonb_array_elements(p_lines) l;
  select sum(round(t.taxable*t.rate/100,2)) into v_source_tax from (
    select sum((l->>'line_extension_amount')::numeric) taxable,(l->>'tax_rate')::numeric rate
    from jsonb_array_elements(p_lines) l group by l->>'tax_category',l->>'tax_rate'
  ) t;
  if h.tax_exclusive_amount is distinct from v_source_net or h.tax_total_amount is distinct from v_source_tax
    or h.line_extension_amount is distinct from v_source_net or h.tax_inclusive_amount is distinct from v_source_net+v_source_tax
    or h.allowance_total_amount <> 0 or h.tax_total_amount_sar is distinct from round(v_source_tax*h.exchange_rate,2)
    or h.payable_amount is distinct from v_source_net+v_source_tax then raise exception 'EINVOICE_ACCOUNTING_SOURCE_MISMATCH'; end if;
  if exists(select 1 from public.vat_documents where organization_id=e.organization_id and document_type='SALES'
    and document_kind=h.document_type and document_number=h.invoice_number and id is distinct from e.accounting_document_id) then
    raise exception 'ACCOUNTING_INVOICE_NUMBER_EXISTS';
  end if;

  if e.accounting_document_id is not null then
    select * into d from public.vat_documents where id=e.accounting_document_id and organization_id=e.organization_id for update;
    if d.id is null or d.document_type<>'SALES' or d.document_kind<>h.document_type then raise exception 'EINVOICE_ACCOUNTING_SOURCE_MISMATCH'; end if;
    select base_currency into v_base from public.organizations where id=e.organization_id;
    -- ZATCA exchange_rate is explicitly quoted to SAR. A different reporting base needs a separate rate.
    if v_base <> 'SAR' then raise exception 'EINVOICE_ACCOUNTING_BASE_CURRENCY_UNSUPPORTED'; end if;
    v_net := round(v_source_net*h.exchange_rate,2);
    v_tax := round(v_source_tax*h.exchange_rate,2);
    v_gross := v_net+v_tax;
    v_changed := d.document_number is distinct from h.invoice_number or d.transaction_date is distinct from h.issue_date
      or d.due_date is distinct from h.due_date or d.counterparty_contact_id is distinct from h.buyer_contact_id
      or d.net_amount is distinct from v_net or d.tax_amount is distinct from v_tax
      or d.source_currency is distinct from h.currency or d.exchange_rate is distinct from h.exchange_rate
      or exists (
        (select item_name,description,quantity,unit_code,unit_price,discount_amount,tax_category,tax_rate
          from jsonb_populate_recordset(null::public.vat_einvoice_lines,p_lines)
         except
         select item_name,description,quantity,unit_code,unit_price,discount_amount,tax_category,tax_rate
          from public.vat_einvoice_lines where invoice_id=e.id)
        union all
        (select item_name,description,quantity,unit_code,unit_price,discount_amount,tax_category,tax_rate
          from public.vat_einvoice_lines where invoice_id=e.id
         except
         select item_name,description,quantity,unit_code,unit_price,discount_amount,tax_category,tax_rate
          from jsonb_populate_recordset(null::public.vat_einvoice_lines,p_lines))
      );
    if v_changed then
      if h.document_type <> 'INVOICE' then raise exception 'VAT_FINANCIAL_EVENT_LOCKED'; end if;
      select event_id into v_event from public.financial_event_links where organization_id=e.organization_id
        and link_type='SOURCE' and target_module='vat_documents' and target_record_id=d.id limit 1;
      select status into v_status from public.financial_events where id=v_event for update;
      if exists(select 1 from public.financial_event_approvals where event_id=v_event and decision='APPROVED') then raise exception 'VAT_FINANCIAL_EVENT_LOCKED'; end if;
      if v_status is null or v_status not in ('DRAFT','PLANNED','COMMITTED') then raise exception 'VAT_FINANCIAL_EVENT_LOCKED'; end if;
      perform 1 from public.liquidity_flows where organization_id=e.organization_id and source_module='VAT_INTEGRATION' and source_record_id=d.id for update;
      if exists(select 1 from public.financial_event_obligation_allocations a join public.financial_event_obligations o on o.id=a.obligation_id where o.event_id=v_event)
        or exists(select 1 from public.liquidity_flows where organization_id=e.organization_id and source_module='VAT_INTEGRATION' and source_record_id=d.id and settled_amount>0)
        or exists(select 1 from public.financial_event_links l join public.financial_events se on se.id=l.event_id
          where l.organization_id=e.organization_id and l.target_module='liquidity_flows' and l.metadata->>'purpose'='SETTLEMENT_INSTRUCTION'
            and se.status not in ('CANCELLED','REVERSED') and l.target_record_id in (
              select id from public.liquidity_flows where organization_id=e.organization_id and source_module='VAT_INTEGRATION' and source_record_id=d.id)) then
        raise exception 'VAT_DOCUMENT_SETTLED_LOCKED';
      end if;
      -- Serialize projection creation for a newly selected customer and keep it in this transaction.
      perform 1 from public.vat_contacts where id=h.buyer_contact_id and organization_id=e.organization_id
        and contact_type in ('CUSTOMER','BOTH') for update;
      if not found then raise exception 'VAT_CONTACT_TYPE_MISMATCH'; end if;
      select counterparty_id into v_counterparty from public.financial_vat_counterparty_map where organization_id=e.organization_id and vat_contact_id=h.buyer_contact_id;
      if v_counterparty is null then
        select id into v_counterparty from public.liquidity_counterparties where organization_id=e.organization_id
          and notes='VAT identity projection: '||h.buyer_contact_id and active limit 1;
        if v_counterparty is null then
          insert into public.liquidity_counterparties(organization_id,name,party_type,contact_name,phone,email,notes)
            select e.organization_id,name,'CUSTOMER','','','','VAT identity projection: '||id
            from public.vat_contacts where id=h.buyer_contact_id returning id into v_counterparty;
        end if;
        insert into public.financial_vat_counterparty_map(organization_id,vat_contact_id,counterparty_id,created_by)
          values(e.organization_id,h.buyer_contact_id,v_counterparty,auth.uid());
      end if;
      select jsonb_agg(jsonb_build_object('description',l->>'item_name','unit',l->>'unit_code','quantity',l->>'quantity',
        'unit_price',round((l->>'unit_price')::numeric*h.exchange_rate,2)::text,'source_unit_price',l->>'unit_price',
        'discount_amount',round((l->>'discount_amount')::numeric*h.exchange_rate,2)::text,'source_discount_amount',l->>'discount_amount',
        'supply_type',case l->>'tax_category' when 'S' then 'STANDARD' when 'Z' then 'ZERO_RATED' when 'E' then 'EXEMPT' else 'OUT_OF_SCOPE' end,
        'net_amount',round((l->>'line_extension_amount')::numeric*h.exchange_rate,2)::text,'source_net_amount',l->>'line_extension_amount',
        'tax_rate',l->>'tax_rate','tax_amount',round((l->>'tax_amount')::numeric*h.exchange_rate,2)::text,'source_tax_amount',l->>'tax_amount',
        'gross_amount',(round((l->>'line_extension_amount')::numeric*h.exchange_rate,2)+round((l->>'tax_amount')::numeric*h.exchange_rate,2))::text,
        'source_gross_amount',l->>'gross_amount') order by (l->>'line_number')::integer) into v_line_items from jsonb_array_elements(p_lines) l;
      update public.vat_documents set document_number=h.invoice_number,transaction_date=h.issue_date,due_date=h.due_date,
        counterparty_contact_id=h.buyer_contact_id,counterparty_name=h.buyer_name,counterparty_tax_number=h.buyer_vat_number,
        net_amount=v_net,tax_amount=v_tax,gross_amount=v_gross,source_currency=h.currency,exchange_rate=h.exchange_rate,
        source_net_amount=v_source_net,source_tax_amount=v_source_tax,source_gross_amount=v_source_net+v_source_tax,
        line_items=v_line_items,tax_rate=case when v_source_net=0 then 0 else round(v_source_tax/v_source_net*100,2) end
        where id=d.id;
      update public.financial_events set counterparty_id=v_counterparty,event_date=h.issue_date,due_date=h.due_date,
        description='Sales invoice '||h.invoice_number,updated_at=now() where id=v_event;
      update public.financial_event_lines l set amount=v_net,base_amount=v_net where l.event_id=v_event
        and l.classification_id in(select id from public.financial_classifications where organization_id=e.organization_id and classification_type='REVENUE');
      if not found then raise exception 'VAT_FINANCIAL_EVENT_LOCKED'; end if;
      select id into v_tax_class from public.financial_classifications where organization_id=e.organization_id and classification_type='TAX' and active limit 1;
      if v_tax_class is null then raise exception 'VAT_FINANCIAL_CLASSIFICATIONS_REQUIRED'; end if;
      update public.financial_event_lines set amount=v_tax,base_amount=v_tax where event_id=v_event and classification_id=v_tax_class;
      if not found and v_tax>0 then
        insert into public.financial_event_lines(event_id,organization_id,line_number,description,classification_id,amount,currency,exchange_rate,base_amount,cash_direction,vat_treatment,vat_rate,vat_amount)
        values(v_event,e.organization_id,2,'Output VAT recognition',v_tax_class,v_tax,'SAR',1,v_tax,'NON_CASH','OUT_OF_SCOPE',0,0);
      end if;
      if v_tax=0 then delete from public.financial_event_lines where event_id=v_event and classification_id=v_tax_class; end if;
      update public.financial_event_obligations set settleable_amount=v_gross,settleable_base_amount=v_gross where event_id=v_event and obligation_type='RECEIVABLE';
      if not found then raise exception 'VAT_FINANCIAL_EVENT_LOCKED'; end if;
      update public.liquidity_flows set amount=v_gross,base_amount=v_gross,due_date=h.due_date,counterparty=h.buyer_name,
        counterparty_id=v_counterparty,reference=h.invoice_number,title='Invoice receivable · '||h.invoice_number,updated_at=now()
        where organization_id=e.organization_id and source_module='VAT_INTEGRATION' and source_record_id=d.id;
    end if;
  end if;
  update public.vat_einvoices set
    accounting_document_id=e.accounting_document_id,
    invoice_number=h.invoice_number,
    document_type=h.document_type,
    invoice_category=h.invoice_category,
    issue_date=h.issue_date,
    issue_time=h.issue_time,
    due_date=h.due_date,
    currency=h.currency,
    exchange_rate=h.exchange_rate,
    buyer_contact_id=h.buyer_contact_id,
    seller_name=h.seller_name,
    seller_vat_number=h.seller_vat_number,
    seller_address=h.seller_address,
    seller_building_number=h.seller_building_number,
    seller_district=h.seller_district,
    seller_additional_number=h.seller_additional_number,
    seller_city=h.seller_city,
    seller_postal_code=h.seller_postal_code,
    seller_country_code=h.seller_country_code,
    buyer_name=h.buyer_name,
    buyer_vat_number=h.buyer_vat_number,
    buyer_address=h.buyer_address,
    buyer_building_number=h.buyer_building_number,
    buyer_district=h.buyer_district,
    buyer_additional_number=h.buyer_additional_number,
    buyer_city=h.buyer_city,
    buyer_postal_code=h.buyer_postal_code,
    buyer_country_code=h.buyer_country_code,
    payment_means_code=h.payment_means_code,
    billing_reference=h.billing_reference,
    preceding_invoice_id=h.preceding_invoice_id,
    note_reason=h.note_reason,
    line_extension_amount=h.line_extension_amount,
    allowance_total_amount=h.allowance_total_amount,
    tax_exclusive_amount=h.tax_exclusive_amount,
    tax_total_amount=h.tax_total_amount,
    tax_inclusive_amount=h.tax_inclusive_amount,
    payable_amount=h.payable_amount,
    tax_total_amount_sar=h.tax_total_amount_sar, updated_at=now()
    where id=e.id returning * into e;
  delete from public.vat_einvoice_lines where invoice_id=e.id;
  insert into public.vat_einvoice_lines(invoice_id,line_number,item_name,description,quantity,unit_code,unit_price,discount_amount,tax_category,tax_rate,tax_exemption_reason_code,tax_exemption_reason,line_extension_amount,tax_amount,gross_amount)
    select e.id,l.line_number,l.item_name,l.description,l.quantity,l.unit_code,l.unit_price,l.discount_amount,l.tax_category,l.tax_rate,l.tax_exemption_reason_code,l.tax_exemption_reason,l.line_extension_amount,l.tax_amount,l.gross_amount
    from jsonb_populate_recordset(null::public.vat_einvoice_lines,p_lines) l;
  return to_jsonb(e)||jsonb_build_object('lines',(select jsonb_agg(to_jsonb(l) order by line_number) from public.vat_einvoice_lines l where invoice_id=e.id));
end $function$

CREATE OR REPLACE FUNCTION public.create_asset_with_acquisition(p_asset jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid();a public.asset_accounts%rowtype;fund public.asset_accounts%rowtype;m jsonb:=coalesce(p_asset->'metadata','{}'::jsonb);org uuid:=nullif(p_asset->>'organization_id','')::uuid;scope text:=coalesce(p_asset->>'ownership_scope','PERSONAL');base text;fx numeric;qty numeric;net numeric;vat numeric;recover numeric;cost numeric;dt date;mode text;tid uuid;wid uuid;eid uuid;cid uuid;taxid uuid;ft text;payload jsonb;lines jsonb;remaining numeric;take numeric;tq numeric;totalq numeric:=0;l record;fingerprint text:=md5(p_asset::text);
begin
 if uid is null then raise exception 'UNAUTHORIZED';end if;
 if p_request_id is null then raise exception 'ASSET_REQUEST_ID_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text||p_request_id::text,0));
 select * into a from public.asset_accounts where user_id=uid and metadata->>'acquisition_request_id'=p_request_id::text;
 if a.id is not null then if a.metadata->>'acquisition_fingerprint'<>fingerprint then raise exception 'ASSET_REQUEST_CONFLICT';end if;return to_jsonb(a);end if;
 if scope='ORGANIZATION' then
  if org is null or not public.has_organization_permission(org,'assets.edit') then raise exception 'ASSET_ORGANIZATION_ACCESS_DENIED';end if;
  select base_currency into base from public.organizations where id=org;
  if p_asset->>'asset_type_code' is null then raise exception 'ASSET_CLASS_AND_TYPE_REQUIRED';end if;
 else
  if org is not null or scope<>'PERSONAL' then raise exception 'ASSET_OWNER_SCOPE_INVALID';end if;
  select base_currency into base from public.profiles where id=uid;
 end if;
 if p_asset->>'asset_type_code' is not null and not exists(select 1 from public.asset_types_v2 t where t.code=p_asset->>'asset_type_code' and t.class_code=p_asset->>'asset_class_code' and t.default_legacy_asset_type::text=p_asset->>'asset_type' and t.active) then raise exception 'ASSET_CLASS_TYPE_MISMATCH';end if;
 fx:=case when p_asset->>'currency'=base then 1 else (m->>'fx_rate')::numeric end;
 qty:=coalesce(nullif(m->>'quantity','')::numeric,1);net:=coalesce(nullif(m->>'purchase_value','')::numeric,nullif(m->>'opening_value','')::numeric,0);dt:=(m->>'purchase_date')::date;
 vat:=coalesce((m->>'vat_amount')::numeric,0);recover:=coalesce((m->>'recoverable_percent')::numeric,100);mode:=coalesce(m->>'acquisition_mode','OPENING_BALANCE');
 if base is null or fx is null or fx<=0 or qty<=0 or net<=0 or dt is null or vat<0 or recover<0 or recover>100 or mode not in('PURCHASE','OPENING_BALANCE') then raise exception 'ASSET_ACQUISITION_INVALID';end if;
 if mode='OPENING_BALANCE' and vat<>0 then raise exception 'OPENING_BALANCE_VAT_NOT_ALLOWED';end if;
 cost:=net+vat*(case when scope='PERSONAL' then 1 else 1-recover/100 end);
 m:=m||jsonb_build_object('fx_rate',fx,'acquisition_base_currency',base,'acquisition_cost_base',cost*fx,'acquisition_request_id',p_request_id,'acquisition_fingerprint',fingerprint);
 insert into public.asset_accounts(user_id,asset_type,name,currency,unit,is_zakatable,ownership_scope,organization_id,entity_id,cost_center_id,asset_class_code,asset_type_code,metadata)
 values(uid,(p_asset->>'asset_type')::public.asset_type,p_asset->>'name',p_asset->>'currency',coalesce(p_asset->>'unit','unit'),coalesce((p_asset->>'is_zakatable')::boolean,true),scope,org,nullif(p_asset->>'entity_id','')::uuid,nullif(p_asset->>'cost_center_id','')::uuid,p_asset->>'asset_class_code',p_asset->>'asset_type_code',m) returning * into a;
 insert into public.transactions(user_id,asset_account_id,organization_id,entity_id,transaction_type,transaction_date,quantity,unit_price,currency,gross_value,base_currency,base_value,reference,metadata,created_by)
 values(uid,a.id,org,a.entity_id,mode::public.transaction_type,dt,qty,net/qty,a.currency,net,base,net*fx,m->>'invoice_reference',m||jsonb_build_object('source','ATOMIC_ASSET_ACQUISITION'),uid) returning id into tid;
 insert into public.lots(user_id,asset_account_id,source_transaction_id,acquisition_date,original_quantity,remaining_quantity,original_value_base,remaining_value_base,status,metadata)
 values(uid,a.id,tid,dt,qty,qty,cost*fx,cost*fx,'ACTIVE',jsonb_build_object('source','ATOMIC_ASSET_ACQUISITION','base_currency',base,'recognition_pending',scope='ORGANIZATION' and mode='PURCHASE'));
 if mode='PURCHASE' and scope='PERSONAL' then
  select * into fund from public.asset_accounts where id=nullif(m->>'funding_account_id','')::uuid and user_id=uid and ownership_scope='PERSONAL' and asset_type in('CASH','BANK') for update;
  if fund.id is null then raise exception 'PERSONAL_PURCHASE_FUNDING_ACCOUNT_INVALID';end if;
  if fund.currency<>a.currency then raise exception 'PERSONAL_PURCHASE_CURRENCY_MISMATCH';end if;
  perform 1 from public.lots where asset_account_id=fund.id and user_id=uid and remaining_quantity>0 order by acquisition_date,created_at,id for update;
  remaining:=(net+vat)*fx;
  if coalesce((select sum(remaining_value_base) from public.lots where asset_account_id=fund.id and user_id=uid and remaining_quantity>0 and acquisition_date<=dt),0)<remaining then raise exception 'PERSONAL_PURCHASE_INSUFFICIENT_FUNDS';end if;
  insert into public.transactions(user_id,asset_account_id,transaction_type,transaction_date,quantity,currency,gross_value,base_currency,base_value,metadata,created_by)
  values(uid,fund.id,'WITHDRAWAL',dt,0,fund.currency,net+vat,base,remaining,jsonb_build_object('source','ASSET_PURCHASE','purchase_transaction_id',tid,'fx_rate',fx),uid) returning id into wid;
  for l in select * from public.lots where asset_account_id=fund.id and user_id=uid and remaining_quantity>0 and remaining_value_base>0 and acquisition_date<=dt order by acquisition_date,created_at,id for update loop
   exit when remaining<=0;take:=least(remaining,l.remaining_value_base);tq:=case when take=l.remaining_value_base then l.remaining_quantity else l.remaining_quantity*take/l.remaining_value_base end;totalq:=totalq+tq;
   insert into public.transaction_allocations(user_id,transaction_id,lot_id,quantity,value_base,allocation_method) values(uid,wid,l.id,tq,take,'FIFO');
   update public.lots set remaining_quantity=greatest(0,remaining_quantity-tq),remaining_value_base=greatest(0,remaining_value_base-take),status=case when take=l.remaining_value_base then 'CLOSED'::public.lot_status else 'PARTIALLY_USED'::public.lot_status end where id=l.id;
   remaining:=remaining-take;
  end loop;
  if remaining>0 then raise exception 'PERSONAL_PURCHASE_INSUFFICIENT_FUNDS';end if;
  update public.transactions set quantity=totalq where id=wid;
 elsif mode='PURCHASE' then
  if nullif(m->>'counterparty_id','') is null or nullif(m->>'invoice_reference','') is null or nullif(m->>'due_date','') is null then raise exception 'ASSET_SUPPLIER_INVOICE_DUE_REQUIRED';end if;
  if (m->>'due_date')::date<dt then raise exception 'ASSET_DUE_BEFORE_PURCHASE';end if;
  if not exists(select 1 from public.liquidity_counterparties where id=(m->>'counterparty_id')::uuid and organization_id=org and party_type in('SUPPLIER','BOTH')) then raise exception 'ASSET_SUPPLIER_SCOPE_MISMATCH';end if;
  ft:=case when a.asset_class_code in('PPE','INTANGIBLE') then 'CAPEX' when a.asset_class_code='INVESTMENT' then 'INVESTMENT' else 'ASSET' end;
  select id into cid from public.financial_classifications where organization_id=org and classification_type=ft and active order by is_system desc limit 1;
  if cid is null then raise exception 'ASSET_FINANCIAL_CLASSIFICATION_REQUIRED';end if;
  lines:=jsonb_build_array(jsonb_build_object('line_number',1,'description',a.name,'classification_id',cid,'cost_center_id',a.cost_center_id,'amount',cost,'currency',a.currency,'exchange_rate',fx,'base_amount',cost*fx,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0));
  if vat*recover>0 then
   select id into taxid from public.financial_classifications where organization_id=org and classification_type='TAX' and active order by is_system desc limit 1;
   if taxid is null then raise exception 'ASSET_VAT_CLASSIFICATION_REQUIRED';end if;
   lines:=lines||jsonb_build_array(jsonb_build_object('line_number',2,'description','Recoverable VAT / '||a.name,'classification_id',taxid,'cost_center_id',a.cost_center_id,'amount',vat*recover/100,'currency',a.currency,'exchange_rate',fx,'base_amount',vat*recover/100*fx,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0));
  end if;
  payload:=jsonb_build_object('organization_id',org,'entity_id',a.entity_id,'counterparty_id',(m->>'counterparty_id')::uuid,'event_type','ASSET_PURCHASE','source_module','ASSETS_INTEGRATION','source_record_id',tid,'source_event_key','asset-purchase:'||tid,'event_date',dt,'due_date',(m->>'due_date')::date,'base_currency',base,'description','Asset purchase / '||a.name,'lines',lines,'obligations',jsonb_build_array(jsonb_build_object('obligation_key','asset-purchase-gross','obligation_type','PAYABLE','settleable_amount',net+vat,'currency',a.currency,'exchange_rate',fx,'base_currency',base,'settleable_base_amount',(net+vat)*fx)),'links',jsonb_build_array(jsonb_build_object('link_type','SOURCE','target_module','transactions','target_record_id',tid,'metadata','{}'::jsonb),jsonb_build_object('link_type','ASSET','target_module','asset_accounts','target_record_id',a.id,'metadata',jsonb_build_object('asset_class_code',a.asset_class_code))));
  eid:=public.create_financial_event_command(payload);
  perform public.ensure_asset_cash_forecast(eid);
  update public.transactions set metadata=metadata||jsonb_build_object('financial_event_id',eid,'financial_core_status','PENDING_APPROVAL','financial_core_intent',payload) where id=tid;
 end if;
 insert into public.audit_logs(user_id,entity_type,entity_id,action,new_data) values(uid,'asset_account',a.id,'ATOMIC_ACQUISITION',jsonb_build_object('transaction_id',tid,'funding_transaction_id',wid,'financial_event_id',eid,'cost_base',cost*fx));
 return to_jsonb(a)||jsonb_build_object('acquisition_transaction_id',tid,'financial_event_id',eid);
end $function$

CREATE OR REPLACE FUNCTION public.prepare_asset_lifecycle(p_asset_id uuid, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid();a public.asset_accounts%rowtype;c public.asset_lifecycle_commands%rowtype;kind text:=p_payload->>'operation';dt date:=(p_payload->>'date')::date;qty numeric:=coalesce((p_payload->>'quantity')::numeric,0);amt numeric:=coalesce((p_payload->>'amount')::numeric,0);q numeric;b numeric;cost numeric;vat numeric:=coalesce((p_payload->>'vat_amount')::numeric,0);cid uuid;aid uuid;taxid uuid;eid uuid;lines jsonb;obs jsonb:='[]';base text;gain numeric;fingerprint text:=md5(p_asset_id::text||p_payload::text);
begin
 if uid is null then raise exception 'UNAUTHORIZED';end if;
 if p_request_id is null then raise exception 'ASSET_REQUEST_ID_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text||p_request_id::text,0));
 select * into c from public.asset_lifecycle_commands where created_by=uid and request_id=p_request_id;
 if c.id is not null then if c.payload_fingerprint<>fingerprint then raise exception 'ASSET_REQUEST_CONFLICT';end if;return to_jsonb(c);end if;
 select * into a from public.asset_accounts where id=p_asset_id and ownership_scope='ORGANIZATION' for update;
 if a.id is null or not public.has_organization_permission(a.organization_id,'assets.edit') then raise exception 'ASSET_ORGANIZATION_ACCESS_DENIED';end if;
 select base_currency into base from public.organizations where id=a.organization_id;
 select sum(remaining_quantity),sum(remaining_value_base) into q,b from public.lots where asset_account_id=a.id and remaining_quantity>0 and coalesce((metadata->>'recognition_pending')::boolean,false)=false;
 if kind not in('DEPRECIATION','SALE','DISPOSAL') or dt is null or amt<0 or vat<0 or (kind<>'SALE' and vat<>0) or q is null or q<=0 or dt<(select min(acquisition_date) from public.lots where asset_account_id=a.id) then raise exception 'ASSET_OPERATION_INVALID';end if;
 if kind='DEPRECIATION' then
  if exists(select 1 from public.asset_lifecycle_commands cmd join public.financial_events e on e.id=cmd.financial_event_id where cmd.asset_account_id=a.id and cmd.operation='DEPRECIATION' and date_trunc('month',cmd.operation_date)=date_trunc('month',dt) and e.status not in('CANCELLED','REVERSED')) then raise exception 'ASSET_DEPRECIATION_PERIOD_EXISTS';end if;
  if a.asset_class_code not in('PPE','INTANGIBLE') or a.asset_type_code in('LAND','GOODWILL') or amt<=0 or amt>b-coalesce((a.metadata->>'residual_value_base')::numeric,0) then raise exception 'ASSET_DEPRECIATION_INVALID';end if;qty:=0;cost:=amt;
 else
  if qty<=0 or qty>q or (kind='DISPOSAL' and amt<>0) then raise exception 'ASSET_QUANTITY_INVALID';end if;
  cost:=b*qty/q;
 end if;
 if kind='SALE' and (nullif(p_payload->>'counterparty_id','') is null or nullif(p_payload->>'due_date','') is null or (p_payload->>'due_date')::date<dt) then raise exception 'ASSET_CUSTOMER_DUE_REQUIRED';end if;
 if kind='SALE' and not exists(select 1 from public.liquidity_counterparties where id=(p_payload->>'counterparty_id')::uuid and organization_id=a.organization_id and party_type in('CUSTOMER','BOTH')) then raise exception 'ASSET_CUSTOMER_SCOPE_MISMATCH';end if;
 gain:=case when kind='SALE' then amt-cost else -cost end;
 select id into cid from public.financial_classifications where organization_id=a.organization_id and classification_type=case when gain>0 then 'REVENUE' else 'OPEX' end and (gain>0 or code='OPEX') and active order by is_system desc limit 1;
 select id into aid from public.financial_classifications where organization_id=a.organization_id and classification_type='ASSET' and active order by is_system desc limit 1;
 if (gain<>0 and cid is null) or (kind='SALE' and cost>0 and aid is null) then raise exception 'ASSET_FINANCIAL_CLASSIFICATION_REQUIRED';end if;
 lines:='[]';
 if gain<>0 then lines:=jsonb_build_array(jsonb_build_object('line_number',1,'description',kind||' / '||a.name,'classification_id',cid,'cost_center_id',a.cost_center_id,'amount',abs(gain),'currency',base,'exchange_rate',1,'base_amount',abs(gain),'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0));end if;
 if kind='SALE' and cost>0 then lines:=lines||jsonb_build_array(jsonb_build_object('line_number',jsonb_array_length(lines)+1,'description','Carrying value released / '||a.name,'classification_id',aid,'cost_center_id',a.cost_center_id,'amount',cost,'currency',base,'exchange_rate',1,'base_amount',cost,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0));end if;
 if kind='SALE' and vat>0 then
  select id into taxid from public.financial_classifications where organization_id=a.organization_id and classification_type='TAX' and active order by is_system desc limit 1;
  if taxid is null then raise exception 'ASSET_VAT_CLASSIFICATION_REQUIRED';end if;
  lines:=lines||jsonb_build_array(jsonb_build_object('line_number',jsonb_array_length(lines)+1,'description','Output VAT / '||a.name,'classification_id',taxid,'cost_center_id',a.cost_center_id,'amount',vat,'currency',base,'exchange_rate',1,'base_amount',vat,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0));
 end if;
 if jsonb_array_length(lines)=0 then raise exception 'ASSET_OPERATION_ZERO_EFFECT';end if;
 if kind='SALE' and amt+vat>0 then obs:=jsonb_build_array(jsonb_build_object('obligation_key','asset-sale-receivable','obligation_type','RECEIVABLE','settleable_amount',amt+vat,'currency',base,'exchange_rate',1,'base_currency',base,'settleable_base_amount',amt+vat));end if;
 insert into public.asset_lifecycle_commands(asset_account_id,organization_id,created_by,request_id,payload_fingerprint,operation,operation_date,quantity,amount,expected_quantity,expected_book_value,book_effect,vat_amount)
 values(a.id,a.organization_id,uid,p_request_id,fingerprint,kind,dt,qty,amt,q,b,cost,vat) returning * into c;
 eid:=public.create_financial_event_command(jsonb_build_object('organization_id',a.organization_id,'entity_id',a.entity_id,'counterparty_id',nullif(p_payload->>'counterparty_id','')::uuid,'event_type','ADJUSTMENT','source_module','ASSET_LIFECYCLE','source_record_id',c.id,'source_event_key','asset-lifecycle:'||c.id,'event_date',dt,'due_date',coalesce(nullif(p_payload->>'due_date','')::date,dt),'base_currency',base,'description',kind||' / '||a.name,'lines',lines,'obligations',obs,'links',jsonb_build_array(jsonb_build_object('link_type','ASSET','target_module','asset_accounts','target_record_id',a.id,'metadata',jsonb_build_object('operation',kind,'quantity_delta',-qty,'asset_effect_base',-cost,'gain_loss_base',gain)))));
 perform public.ensure_asset_cash_forecast(eid);
 -- The Core INSERT trigger stores the event link; UPDATE rights are not public.
 return to_jsonb(c)||jsonb_build_object('financial_event_id',eid);
end $function$

CREATE OR REPLACE FUNCTION public.prepare_vat_financial_event(p_source_table text, p_source_id uuid, p_entity_id uuid, p_due_date date DEFAULT NULL::date, p_original_event_id uuid DEFAULT NULL::uuid, p_alias_event_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions'
AS $function$
declare d public.vat_documents%rowtype;eid uuid;cls uuid;taxcls uuid;cp uuid;gross numeric;payload jsonb;existing public.financial_vat_source_bindings%rowtype;contact public.vat_contacts%rowtype;
begin
if auth.uid() is null then raise exception 'UNAUTHORIZED';end if;if p_source_table<>'vat_documents' then raise exception 'VAT_SOURCE_TABLE_NOT_ENABLED_ON_PRODUCTION_ADAPTER';end if;
select * into d from public.vat_documents where id=p_source_id;if d.id is null then raise exception 'VAT_SOURCE_NOT_FOUND';end if;
if d.document_type<>'PURCHASE' then raise exception 'VAT_PURCHASE_ADAPTER_REQUIRED';end if;
if not public.financial_core_can(d.organization_id,'financial_core.create') or not public.has_organization_permission(d.organization_id,'vat.view') then raise exception 'VAT_FINANCIAL_PREPARE_DENIED';end if;
if not exists(select 1 from public.organization_entities where id=p_entity_id and organization_id=d.organization_id and active) then raise exception 'VAT_ENTITY_ORGANIZATION_MISMATCH';end if;
select * into existing from public.financial_vat_source_bindings where organization_id=d.organization_id and source_table='vat_documents' and source_record_id=d.id;if found then return existing.event_id;end if;
select id into cls from public.financial_classifications where organization_id=d.organization_id and classification_type='OPEX' and code='OPEX' and active limit 1;
select id into taxcls from public.financial_classifications where organization_id=d.organization_id and classification_type='TAX' and active order by is_system desc limit 1;
if cls is null or taxcls is null then raise exception 'VAT_FINANCIAL_CLASSIFICATIONS_REQUIRED';end if;
if d.counterparty_contact_id is null then raise exception 'VAT_STABLE_CONTACT_REQUIRED';end if;
select counterparty_id into cp from public.financial_vat_counterparty_map where organization_id=d.organization_id and vat_contact_id=d.counterparty_contact_id;
if cp is null then select * into contact from public.vat_contacts where id=d.counterparty_contact_id and organization_id=d.organization_id;if contact.id is null then raise exception 'VAT_CONTACT_NOT_FOUND';end if;
insert into public.liquidity_counterparties(organization_id,name,party_type,email,phone,notes,created_by) values(d.organization_id,contact.name,'SUPPLIER',coalesce(contact.email,''),coalesce(contact.phone,''),'VAT identity projection: '||contact.id,auth.uid()) returning id into cp;
insert into public.financial_vat_counterparty_map(organization_id,vat_contact_id,counterparty_id,created_by) values(d.organization_id,contact.id,cp,auth.uid());end if;
gross:=d.gross_amount;
payload:=jsonb_build_object('organization_id',d.organization_id,'entity_id',p_entity_id,'counterparty_id',cp,'event_type','EXPENSE','source_module','VAT_INTEGRATION','source_record_id',d.id,'source_event_key','vat_documents:'||d.id,'event_date',d.transaction_date,'due_date',coalesce(p_due_date,d.transaction_date),'base_currency',(select base_currency from public.organizations where id=d.organization_id),'description','VAT purchase recognition','lines',
jsonb_build_array(jsonb_build_object('line_number',1,'classification_id',cls,'amount',d.net_amount,'currency',(select base_currency from public.organizations where id=d.organization_id),'exchange_rate',1,'base_amount',d.net_amount,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0,'metadata',jsonb_build_object('source_role','NET_RECOGNITION')))||
case when d.tax_amount>0 then jsonb_build_array(jsonb_build_object('line_number',2,'classification_id',taxcls,'amount',d.tax_amount,'currency',(select base_currency from public.organizations where id=d.organization_id),'exchange_rate',1,'base_amount',d.tax_amount,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0,'metadata',jsonb_build_object('source_role','INPUT_VAT','recoverable_percent',d.recoverable_percent)))else '[]'::jsonb end,
'obligations',jsonb_build_array(jsonb_build_object('obligation_key','invoice-gross','obligation_type','PAYABLE','settleable_amount',gross,'currency',(select base_currency from public.organizations where id=d.organization_id),'exchange_rate',1,'base_currency',(select base_currency from public.organizations where id=d.organization_id),'settleable_base_amount',gross)),
'links',jsonb_build_array(jsonb_build_object('link_type','SOURCE','target_module','vat_documents','target_record_id',d.id)));
eid:=private.phase2c_create_financial_event_internal(payload);
perform public.transition_financial_event(eid,'PLANNED','VAT integration prepare');perform public.transition_financial_event(eid,'COMMITTED','VAT integration pending approval');
insert into public.financial_vat_source_bindings(organization_id,source_table,source_record_id,event_id,canonical_payload,payload_fingerprint,document_kind,side,contact_id,entity_id,due_date,original_event_id,is_alias,created_by)
values(d.organization_id,'vat_documents',d.id,eid,private.canonical_financial_json(to_jsonb(d)),encode(extensions.digest(convert_to(d.id::text||'|'||eid::text,'UTF8'),'sha256'),'hex'),d.document_kind,'PURCHASE',d.counterparty_contact_id,p_entity_id,coalesce(p_due_date,d.transaction_date),p_original_event_id,false,auth.uid());
return eid;end$function$

CREATE OR REPLACE FUNCTION public.prepare_vat_note_financial_event(p_document_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.vat_documents%rowtype; original public.vat_documents%rowtype;
 root public.financial_events%rowtype; ob public.financial_event_obligations%rowtype;
 eid uuid; cls uuid; taxcls uuid; existing uuid; payload jsonb; obligations jsonb; canonical jsonb;
begin
 if auth.uid() is null then raise exception 'UNAUTHORIZED'; end if;
 select * into d from public.vat_documents where id=p_document_id for update;
 if d.id is null then raise exception 'VAT_SOURCE_NOT_FOUND'; end if;
 if not public.is_organization_admin(d.organization_id) or not public.financial_core_can(d.organization_id,'financial_core.create') then raise exception 'VAT_FINANCIAL_PREPARE_DENIED'; end if;
 if d.document_kind not in ('CREDIT_NOTE','DEBIT_NOTE') or d.preceding_document_id is null or nullif(trim(d.notes),'') is null then raise exception 'VAT_NOTE_REFERENCE_AND_REASON_REQUIRED'; end if;
 select * into original from public.vat_documents where id=d.preceding_document_id and organization_id=d.organization_id for update;
 if original.id is null or original.document_kind<>'INVOICE' or original.document_type<>d.document_type or original.counterparty_contact_id is distinct from d.counterparty_contact_id
  or original.currency<>d.currency or coalesce(original.source_currency,original.currency)<>coalesce(d.source_currency,d.currency) or original.exchange_rate<>d.exchange_rate then raise exception 'VAT_NOTE_ORIGINAL_IDENTITY_OR_CURRENCY_MISMATCH'; end if;
 if d.transaction_date<original.transaction_date then raise exception 'VAT_NOTE_DATE_BEFORE_ORIGINAL'; end if;
 select e.* into root from public.financial_event_links l join public.financial_events e on e.id=l.event_id and e.organization_id=l.organization_id
 where l.organization_id=d.organization_id and l.link_type='SOURCE' and l.target_module='vat_documents' and l.target_record_id=original.id;
 if root.id is null or root.status in ('CANCELLED','REVERSED') then raise exception 'VAT_ORIGINAL_FINANCIAL_EVENT_REQUIRED'; end if;
 select event_id into existing from public.financial_vat_source_bindings where organization_id=d.organization_id and source_table='vat_documents' and source_record_id=d.id;
 if existing is not null then return existing; end if;
 select * into ob from public.financial_event_obligations where organization_id=d.organization_id and event_id=root.id and adjusts_obligation_id is null and obligation_type=case when d.document_type='SALES' then 'RECEIVABLE' else 'PAYABLE' end for update;
 if ob.id is null then raise exception 'VAT_ORIGINAL_OBLIGATION_REQUIRED'; end if;
 select l.classification_id into cls from public.financial_event_lines l join public.financial_classifications c on c.id=l.classification_id
 where l.event_id=root.id and c.classification_type<>'TAX' order by l.line_number limit 1;
 select l.classification_id into taxcls from public.financial_event_lines l join public.financial_classifications c on c.id=l.classification_id
 where l.event_id=root.id and c.classification_type='TAX' order by l.line_number limit 1;
 if taxcls is null then select id into taxcls from public.financial_classifications where organization_id=d.organization_id and classification_type='TAX' and active order by is_system desc limit 1; end if;
 if cls is null or (d.tax_amount>0 and taxcls is null) then raise exception 'VAT_FINANCIAL_CLASSIFICATIONS_REQUIRED'; end if;
 obligations:=case when d.document_kind='CREDIT_NOTE' then jsonb_build_array(jsonb_build_object('obligation_key','note-adjustment','obligation_type',ob.obligation_type,'adjusts_obligation_id',ob.id,'adjustment_effect','DECREASE','settleable_amount',d.gross_amount,'currency',d.currency,'exchange_rate',1,'base_currency',d.currency,'settleable_base_amount',d.gross_amount))
 else jsonb_build_array(jsonb_build_object('obligation_key','note-gross','obligation_type',ob.obligation_type,'settleable_amount',d.gross_amount,'currency',d.currency,'exchange_rate',1,'base_currency',d.currency,'settleable_base_amount',d.gross_amount)) end;
 payload:=jsonb_build_object('organization_id',d.organization_id,'entity_id',root.entity_id,'counterparty_id',root.counterparty_id,'event_type','ADJUSTMENT','source_module','VAT_INTEGRATION','source_record_id',d.id,'source_event_key','vat_documents:'||d.id,'event_date',d.transaction_date,'due_date',coalesce(d.due_date,d.transaction_date),'base_currency',d.currency,'description',d.document_kind||' '||d.document_number||' / '||original.document_number,
 'lines',jsonb_build_array(jsonb_build_object('line_number',1,'classification_id',cls,'amount',d.net_amount,'currency',d.currency,'exchange_rate',1,'base_amount',d.net_amount,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0,'metadata',jsonb_build_object('source_role','NET_RECOGNITION','recognition_sign',case when d.document_kind='CREDIT_NOTE' then -1 else 1 end))) ||
 case when d.tax_amount>0 then jsonb_build_array(jsonb_build_object('line_number',2,'classification_id',taxcls,'amount',d.tax_amount,'currency',d.currency,'exchange_rate',1,'base_amount',d.tax_amount,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0,'metadata',jsonb_build_object('source_role',case when d.document_type='SALES' then 'OUTPUT_VAT' else 'INPUT_VAT' end,'recognition_sign',case when d.document_kind='CREDIT_NOTE' then -1 else 1 end,'recoverable_percent',d.recoverable_percent))) else '[]'::jsonb end,
 'obligations',obligations,'links',jsonb_build_array(jsonb_build_object('link_type','SOURCE','target_module','vat_documents','target_record_id',d.id),jsonb_build_object('link_type','CORRECTS','related_event_id',root.id,'metadata',jsonb_build_object('original_document_id',original.id,'reason',d.notes))));
 eid:=private.phase2c_create_financial_event_internal(payload);
 perform public.transition_financial_event(eid,'PLANNED','VAT note prepared');
 perform public.transition_financial_event(eid,'COMMITTED','VAT note pending financial approval');
 canonical:=private.canonical_financial_json(jsonb_build_object('adapter','LINKED_NOTE_V1','document',to_jsonb(d)-'zatca_status'));
 insert into public.financial_vat_source_bindings(organization_id,source_table,source_record_id,event_id,canonical_payload,payload_fingerprint,document_kind,side,contact_id,entity_id,due_date,original_event_id,is_alias,created_by)
 values(d.organization_id,'vat_documents',d.id,eid,canonical,encode(extensions.digest(convert_to(canonical::text,'UTF8'),'sha256'),'hex'),d.document_kind,d.document_type,d.counterparty_contact_id,root.entity_id,coalesce(d.due_date,d.transaction_date),root.id,false,auth.uid());
 return eid;
end $function$

CREATE OR REPLACE FUNCTION public.purchase_existing_asset(p_asset_id uuid, p_asset jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare uid uuid:=auth.uid();a public.asset_accounts%rowtype;fund public.asset_accounts%rowtype;m jsonb:=coalesce(p_asset->'metadata','{}'::jsonb);org uuid:=nullif(p_asset->>'organization_id','')::uuid;scope text:=coalesce(p_asset->>'ownership_scope','PERSONAL');base text;fx numeric;qty numeric;net numeric;vat numeric;recover numeric;cost numeric;dt date;mode text;tid uuid;wid uuid;eid uuid;cid uuid;taxid uuid;ft text;payload jsonb;lines jsonb;remaining numeric;take numeric;tq numeric;totalq numeric:=0;l record;fingerprint text:=md5(p_asset::text);
begin
 if uid is null then raise exception 'UNAUTHORIZED';end if;
 if p_request_id is null then raise exception 'ASSET_REQUEST_ID_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text||p_request_id::text,0));
 select t.id into tid from public.transactions t where t.user_id=uid and t.metadata->>'acquisition_request_id'=p_request_id::text;
 if tid is not null then if not exists(select 1 from public.transactions t where t.id=tid and t.asset_account_id=p_asset_id and t.metadata->>'acquisition_fingerprint'=fingerprint) then raise exception 'ASSET_REQUEST_CONFLICT';end if;return (select to_jsonb(t) from public.transactions t where id=tid);end if;
 if scope='ORGANIZATION' then
  if org is null or not public.has_organization_permission(org,'assets.edit') then raise exception 'ASSET_ORGANIZATION_ACCESS_DENIED';end if;
  select base_currency into base from public.organizations where id=org;
  if p_asset->>'asset_type_code' is null then raise exception 'ASSET_CLASS_AND_TYPE_REQUIRED';end if;
 else
  if org is not null or scope<>'PERSONAL' then raise exception 'ASSET_OWNER_SCOPE_INVALID';end if;
  select base_currency into base from public.profiles where id=uid;
 end if;
 if p_asset->>'asset_type_code' is not null and not exists(select 1 from public.asset_types_v2 t where t.code=p_asset->>'asset_type_code' and t.class_code=p_asset->>'asset_class_code' and t.default_legacy_asset_type::text=p_asset->>'asset_type' and t.active) then raise exception 'ASSET_CLASS_TYPE_MISMATCH';end if;
 fx:=case when p_asset->>'currency'=base then 1 else (m->>'fx_rate')::numeric end;
 qty:=coalesce(nullif(m->>'quantity','')::numeric,1);net:=coalesce(nullif(m->>'purchase_value','')::numeric,nullif(m->>'opening_value','')::numeric,0);dt:=(m->>'purchase_date')::date;
 vat:=coalesce((m->>'vat_amount')::numeric,0);recover:=coalesce((m->>'recoverable_percent')::numeric,100);mode:=coalesce(m->>'acquisition_mode','OPENING_BALANCE');
 if base is null or fx is null or fx<=0 or qty<=0 or net<=0 or dt is null or vat<0 or recover<0 or recover>100 or mode not in('PURCHASE','OPENING_BALANCE') then raise exception 'ASSET_ACQUISITION_INVALID';end if;
 if mode='OPENING_BALANCE' and vat<>0 then raise exception 'OPENING_BALANCE_VAT_NOT_ALLOWED';end if;
 cost:=net+vat*(case when scope='PERSONAL' then 1 else 1-recover/100 end);
 m:=m||jsonb_build_object('fx_rate',fx,'acquisition_base_currency',base,'acquisition_cost_base',cost*fx,'acquisition_request_id',p_request_id,'acquisition_fingerprint',fingerprint);
 select * into a from public.asset_accounts where id=p_asset_id for update;
 if a.id is null or a.currency is distinct from p_asset->>'currency' or a.ownership_scope is distinct from scope or a.organization_id is distinct from org or (scope='PERSONAL' and a.user_id<>uid) then raise exception 'ASSET_ACQUISITION_SCOPE_MISMATCH';end if;
 if mode<>'PURCHASE' then raise exception 'ASSET_PURCHASE_REQUIRED';end if;
 insert into public.transactions(user_id,asset_account_id,organization_id,entity_id,transaction_type,transaction_date,quantity,unit_price,currency,gross_value,base_currency,base_value,reference,metadata,created_by)
 values(uid,a.id,org,a.entity_id,mode::public.transaction_type,dt,qty,net/qty,a.currency,net,base,net*fx,m->>'invoice_reference',m||jsonb_build_object('source','ATOMIC_ASSET_ACQUISITION'),uid) returning id into tid;
 insert into public.lots(user_id,asset_account_id,source_transaction_id,acquisition_date,original_quantity,remaining_quantity,original_value_base,remaining_value_base,status,metadata)
 values(uid,a.id,tid,dt,qty,qty,cost*fx,cost*fx,'ACTIVE',jsonb_build_object('source','ATOMIC_ASSET_ACQUISITION','base_currency',base,'recognition_pending',scope='ORGANIZATION' and mode='PURCHASE'));
 if mode='PURCHASE' and scope='PERSONAL' then
  select * into fund from public.asset_accounts where id=nullif(m->>'funding_account_id','')::uuid and user_id=uid and ownership_scope='PERSONAL' and asset_type in('CASH','BANK') for update;
  if fund.id is null then raise exception 'PERSONAL_PURCHASE_FUNDING_ACCOUNT_INVALID';end if;
  if fund.currency<>a.currency then raise exception 'PERSONAL_PURCHASE_CURRENCY_MISMATCH';end if;
  perform 1 from public.lots where asset_account_id=fund.id and user_id=uid and remaining_quantity>0 order by acquisition_date,created_at,id for update;
  remaining:=(net+vat)*fx;
  if coalesce((select sum(remaining_value_base) from public.lots where asset_account_id=fund.id and user_id=uid and remaining_quantity>0 and acquisition_date<=dt),0)<remaining then raise exception 'PERSONAL_PURCHASE_INSUFFICIENT_FUNDS';end if;
  insert into public.transactions(user_id,asset_account_id,transaction_type,transaction_date,quantity,currency,gross_value,base_currency,base_value,metadata,created_by)
  values(uid,fund.id,'WITHDRAWAL',dt,0,fund.currency,net+vat,base,remaining,jsonb_build_object('source','ASSET_PURCHASE','purchase_transaction_id',tid,'fx_rate',fx),uid) returning id into wid;
  for l in select * from public.lots where asset_account_id=fund.id and user_id=uid and remaining_quantity>0 and remaining_value_base>0 and acquisition_date<=dt order by acquisition_date,created_at,id for update loop
   exit when remaining<=0;take:=least(remaining,l.remaining_value_base);tq:=case when take=l.remaining_value_base then l.remaining_quantity else l.remaining_quantity*take/l.remaining_value_base end;totalq:=totalq+tq;
   insert into public.transaction_allocations(user_id,transaction_id,lot_id,quantity,value_base,allocation_method) values(uid,wid,l.id,tq,take,'FIFO');
   update public.lots set remaining_quantity=greatest(0,remaining_quantity-tq),remaining_value_base=greatest(0,remaining_value_base-take),status=case when take=l.remaining_value_base then 'CLOSED'::public.lot_status else 'PARTIALLY_USED'::public.lot_status end where id=l.id;
   remaining:=remaining-take;
  end loop;
  if remaining>0 then raise exception 'PERSONAL_PURCHASE_INSUFFICIENT_FUNDS';end if;
  update public.transactions set quantity=totalq where id=wid;
 elsif mode='PURCHASE' then
  if nullif(m->>'counterparty_id','') is null or nullif(m->>'invoice_reference','') is null or nullif(m->>'due_date','') is null then raise exception 'ASSET_SUPPLIER_INVOICE_DUE_REQUIRED';end if;
  if (m->>'due_date')::date<dt then raise exception 'ASSET_DUE_BEFORE_PURCHASE';end if;
  if not exists(select 1 from public.liquidity_counterparties where id=(m->>'counterparty_id')::uuid and organization_id=org and party_type in('SUPPLIER','BOTH')) then raise exception 'ASSET_SUPPLIER_SCOPE_MISMATCH';end if;
  ft:=case when a.asset_class_code in('PPE','INTANGIBLE') then 'CAPEX' when a.asset_class_code='INVESTMENT' then 'INVESTMENT' else 'ASSET' end;
  select id into cid from public.financial_classifications where organization_id=org and classification_type=ft and active order by is_system desc limit 1;
  if cid is null then raise exception 'ASSET_FINANCIAL_CLASSIFICATION_REQUIRED';end if;
  lines:=jsonb_build_array(jsonb_build_object('line_number',1,'description',a.name,'classification_id',cid,'cost_center_id',a.cost_center_id,'amount',cost,'currency',a.currency,'exchange_rate',fx,'base_amount',cost*fx,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0));
  if vat*recover>0 then
   select id into taxid from public.financial_classifications where organization_id=org and classification_type='TAX' and active order by is_system desc limit 1;
   if taxid is null then raise exception 'ASSET_VAT_CLASSIFICATION_REQUIRED';end if;
   lines:=lines||jsonb_build_array(jsonb_build_object('line_number',2,'description','Recoverable VAT / '||a.name,'classification_id',taxid,'cost_center_id',a.cost_center_id,'amount',vat*recover/100,'currency',a.currency,'exchange_rate',fx,'base_amount',vat*recover/100*fx,'cash_direction','NON_CASH','vat_treatment','OUT_OF_SCOPE','vat_rate',0,'vat_amount',0));
  end if;
  payload:=jsonb_build_object('organization_id',org,'entity_id',a.entity_id,'counterparty_id',(m->>'counterparty_id')::uuid,'event_type','ASSET_PURCHASE','source_module','ASSETS_INTEGRATION','source_record_id',tid,'source_event_key','asset-purchase:'||tid,'event_date',dt,'due_date',(m->>'due_date')::date,'base_currency',base,'description','Asset purchase / '||a.name,'lines',lines,'obligations',jsonb_build_array(jsonb_build_object('obligation_key','asset-purchase-gross','obligation_type','PAYABLE','settleable_amount',net+vat,'currency',a.currency,'exchange_rate',fx,'base_currency',base,'settleable_base_amount',(net+vat)*fx)),'links',jsonb_build_array(jsonb_build_object('link_type','SOURCE','target_module','transactions','target_record_id',tid,'metadata','{}'::jsonb),jsonb_build_object('link_type','ASSET','target_module','asset_accounts','target_record_id',a.id,'metadata',jsonb_build_object('asset_class_code',a.asset_class_code))));
  eid:=public.create_financial_event_command(payload);
  perform public.ensure_asset_cash_forecast(eid);
  update public.transactions set metadata=metadata||jsonb_build_object('financial_event_id',eid,'financial_core_status','PENDING_APPROVAL','financial_core_intent',payload) where id=tid;
 end if;
 insert into public.audit_logs(user_id,entity_type,entity_id,action,new_data) values(uid,'asset_account',a.id,'ATOMIC_ACQUISITION',jsonb_build_object('transaction_id',tid,'funding_transaction_id',wid,'financial_event_id',eid,'cost_base',cost*fx));
 return (select to_jsonb(t) from public.transactions t where id=tid);
end $function$
